  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  pseudo    String\n  password  String\n  createdAt DateTime @default(now())\n\n  company Company?\n}\n\nmodel Company {\n  id          String   @id @default(uuid())\n  name        String\n  liveryColor String   @default(\"#f2a900\")\n  balance     Int      @default(500) // trésorerie, en pièces\n  maxTrains   Int      @default(2) // capacité du dépôt, extensible contre paiement\n  isPremium   Boolean  @default(false) // débloque les modèles de trains exclusifs\n  createdAt   DateTime @default(now())\n\n  owner   User   @relation(fields: [ownerId], references: [id])\n  ownerId String @unique\n\n  trains          Train[]\n  lines           Line[]\n  contracts       Contract[]\n  transactions    Transaction[]\n  dailyChallenges DailyChallenge[]\n  staff           Staff[]\n}\n\nmodel Line {\n  id               String @id @default(uuid())\n  name             String\n  departureStation String\n  arrivalStation   String\n  durationMinutes  Int // temps de trajet simulé, en minutes\n\n  company   Company @relation(fields: [companyId], references: [id])\n  companyId String\n\n  trains Train[]\n\n  createdAt DateTime @default(now())\n}\n\nenum TrainStatus {\n  IDLE // à quai, disponible pour une ligne ou un contrat de fret\n  EN_ROUTE // en circulation (ligne voyageurs ou livraison de fret)\n  MAINTENANCE // indisponible\n}\n\nmodel Train {\n  id     String      @id @default(uuid())\n  name   String\n  model  String      @default(\"STANDARD\") // STANDARD | EXPRESS | FRET_LOURD (Premium)\n  status TrainStatus @default(IDLE)\n\n  // progression du trajet en cours (0 = départ, 100 = arrivé)\n  progress   Int       @default(0)\n  departedAt DateTime?\n\n  // usure du matériel (0 = neuf, 100 = en panne, nécessite réparation)\n  wear Int @default(0)\n\n  company   Company @relation(fields: [companyId], references: [id])\n  companyId String\n\n  line   Line?   @relation(fields: [lineId], references: [id])\n  lineId String?\n\n  contract Contract?\n\n  incidents Incident[]\n\n  purchasedAt DateTime @default(now())\n}\n\nenum ContractStatus {\n  DISPONIBLE // offre sur le marché, pas encore prise\n  EN_COURS // acceptée, un train livre la marchandise\n  LIVREE // terminée, récompense versée\n}\n\nmodel Contract {\n  id                 String  @id @default(uuid())\n  cargoType          String // type de marchandise transportée\n  originStation      String\n  destinationStation String\n  durationMinutes    Int // temps de livraison simulé\n  reward             Int // récompense versée à la livraison\n  risky              Boolean @default(false) // marchandise fragile : récompense plus élevée mais risque de dommage\n\n  status     ContractStatus @default(DISPONIBLE)\n  acceptedAt DateTime?\n  expiresAt  DateTime? // au-delà, l'offre disparaît du marché si non acceptée\n\n  company   Company? @relation(fields: [companyId], references: [id])\n  companyId String?\n\n  train   Train?  @relation(fields: [trainId], references: [id])\n  trainId String? @unique\n\n  createdAt DateTime @default(now())\n}\n\nmodel Incident {\n  id      String @id @default(uuid())\n  message String\n\n  train   Train  @relation(fields: [trainId], references: [id])\n  trainId String\n\n  createdAt DateTime @default(now())\n}\n\nmodel Transaction {\n  id          String @id @default(uuid())\n  type        String // ACHAT_TRAIN | REPARATION | FRET | FONDATION\n  amount      Int // positif = recette, négatif = dépense\n  description String\n\n  company   Company @relation(fields: [companyId], references: [id])\n  companyId String\n\n  createdAt DateTime @default(now())\n}\n\nmodel DailyChallenge {\n  id      String  @id @default(uuid())\n  date    String // \"YYYY-MM-DD\", jour auquel ce défi appartient\n  type    String // LIVRAISONS | REPARATIONS | NOUVELLE_LIGNE\n  target  Int\n  reward  Int\n  claimed Boolean @default(false)\n\n  company   Company @relation(fields: [companyId], references: [id])\n  companyId String\n\n  createdAt DateTime @default(now())\n\n  @@unique([companyId, date])\n}\n\nmodel Staff {\n  id            String   @id @default(uuid())\n  role          String // MECANICIEN | CHEF_DEPOT\n  salaryPerTick Int\n  hiredAt       DateTime @default(now())\n\n  company   Company @relation(fields: [companyId], references: [id])\n  companyId String\n\n  @@unique([companyId, role])\n}\n\nmodel WeatherEvent {\n  id        String   @id @default(uuid())\n  type      String // BROUILLARD | CANICULE | VERGLAS\n  startedAt DateTime @default(now())\n  endsAt    DateTime\n}\n",
